{"policy_source":"from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes: int):
        self.capacity_bytes = max(0, int(capacity_bytes))
        self.t1 = OrderedDict()
        self.t2 = OrderedDict()
        self.b1 = OrderedDict()
        self.b2 = OrderedDict()
        self.t1_bytes = 0
        self.t2_bytes = 0
        self.used_bytes = 0
        self.target_t1 = self.capacity_bytes // 2
        self.ghost_limit = 4096

    def _remember(self, ghost, key):
        ghost.pop(key, None)
        ghost[key] = None
        while len(ghost) > self.ghost_limit:
            ghost.popitem(last=False)

    def _forget(self, key):
        self.b1.pop(key, None)
        self.b2.pop(key, None)

    def _evict_t1(self):
        if not self.t1:
            return None
        key, size = self.t1.popitem(last=False)
        self.t1_bytes -= size
        self.used_bytes -= size
        self._remember(self.b1, key)
        return key

    def _evict_t2(self):
        if not self.t2:
            return None
        key, size = self.t2.popitem(last=False)
        self.t2_bytes -= size
        self.used_bytes -= size
        self._remember(self.b2, key)
        return key

    def _replace(self, from_b2=False):
        if self.t1 and (self.t1_bytes > self.target_t1 or (from_b2 and self.t1_bytes == self.target_t1)):
            return self._evict_t1()
        if self.t2:
            return self._evict_t2()
        return self._evict_t1()

    def access(self, key: int, size: int, now: int) -> list[int]:
        if key in self.t1:
            stored_size = self.t1.pop(key)
            self.t1_bytes -= stored_size
            self.t2[key] = stored_size
            self.t2_bytes += stored_size
            return []

        if key in self.t2:
            stored_size = self.t2.pop(key)
            self.t2[key] = stored_size
            return []

        if size <= 0 or self.capacity_bytes == 0 or size > self.capacity_bytes:
            return []

        step = max(1, min(size, self.capacity_bytes))
        from_b2 = key in self.b2
        if key in self.b1:
            self.target_t1 = min(self.capacity_bytes, self.target_t1 + step)
        elif from_b2:
            self.target_t1 = max(0, self.target_t1 - step)
        self._forget(key)

        evicted = []
        while self.used_bytes + size > self.capacity_bytes:
            victim = self._replace(from_b2)
            if victim is None:
                break
            evicted.append(victim)

        self.t1[key] = size
        self.t1_bytes += size
        self.used_bytes += size
        return evicted
